CREATE PROCEDURE [dbo].[sp_backup_differential]
	@DbName NVARCHAR(128)= 'HRISMAIN',
	@BackupPath NVARCHAR(256) = 'C:\Backups\Data\'
AS
DECLARE @BackupCommand NVARCHAR(MAX);

SET @BackupPath = @BackupPath + @DbName + '_Diff_' + REPLACE(CONVERT(VARCHAR(19), GETDATE(), 120), ':', '-') + '.bak';

SET @BackupCommand = 
    'BACKUP DATABASE [' + @DbName + '] ' +
    'TO DISK = ''' + @BackupPath + ''' ' +
    'WITH DIFFERENTIAL, NAME = ''Differential Backup of [' + @DbName + ']'', FORMAT';

EXEC sp_executesql @BackupCommand;

CREATE PROCEDURE [dbo].[sp_backup_full]
	@DbName NVARCHAR(128)= 'HRISMAIN',
	@BackupPath NVARCHAR(256) = 'C:\Backups\Data\'
AS
	DECLARE @BackupCommand NVARCHAR(MAX);
	SET @BackupPath = @BackupPath + @DbName + '_Full_' + REPLACE(CONVERT(VARCHAR(19), GETDATE(), 120), ':', '-') + '.bak';

	SET @BackupCommand = 
			'BACKUP DATABASE [' + @DbName + '] ' +
			'TO DISK = ''' + @BackupPath + ''' ' +
			'WITH INIT, NAME = ''Full Backup of [' + @DbName + ']'', FORMAT';

	EXEC sp_executesql @BackupCommand;

CREATE PROCEDURE [dbo].[sp_backup_transaction_log]
	@DbName NVARCHAR(128)= 'HRISMAIN',
	@BackupPath NVARCHAR(256) = 'C:\Backups\Data\'
AS
DECLARE @BackupCommand NVARCHAR(MAX);

SET @BackupPath = @BackupPath + @DbName + '_TransactionLog_' + REPLACE(CONVERT(VARCHAR(19), GETDATE(), 120), ':', '-') + '.trn';

SET @BackupCommand = 
    'BACKUP LOG [' + @DbName + '] ' +
    'TO DISK = ''' + @BackupPath + ''' ' +
    'WITH NAME = ''Transaction Log Backup of [' + @DbName + ']'', FORMAT';

EXEC sp_executesql @BackupCommand;

create PROCEDURE [dbo].[sp_payslipwithvaluedelete]
    @uname NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRAN;

        DELETE FROM otchart
        WHERE uname = @uname;

        COMMIT TRAN;

        -- Optional: return affected rows
        SELECT @@ROWCOUNT AS RowsDeleted;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRAN;

        -- Return error info
        SELECT 
            ERROR_MESSAGE() AS ErrorMessage,
            ERROR_LINE() AS ErrorLine;
    END CATCH
END

